.dark{--app-theme-sidebar-row-hover:#ffffff0b!important;--app-theme-sidebar-row-active:#ffffff12!important;--app-theme-sidebar-row-selected:#ffffff0f!important}
.dark [data-thread-item],.dark [data-sidebar-row]{border-radius:10px}
.dark [data-sidebar-row][aria-current]:not([aria-current=false]){box-shadow:inset 0 0 0 1px #aaaaff24,inset 0 1px #ffffff1a,0 8px 20px -12px #000b;backdrop-filter:blur(10px)}
.dark [data-slot="composer-host"]{background:linear-gradient(180deg,rgba(20,22,56,.6),rgba(8,10,30,.7))!important;backdrop-filter:blur(18px) saturate(140%);border:1px solid rgba(132,136,235,.44)!important;border-radius:14px;box-shadow:0 14px 40px -18px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,255,255,.08);transition:border-color .2s ease}
.dark [data-slot="composer-host"]:focus-within{border-color:rgba(150,146,235,.5)!important}
.dark [data-slot="composer-host"] > *{background-color:transparent}
.dark [data-user-message-bubble]{background:rgba(30,24,64,.85)!important;border:1px solid rgba(170,150,255,.12);backdrop-filter:blur(6px)}
.dark .chat-markdown{text-shadow:0 1px 2px rgba(5,4,15,.6)}
.dark .chat-markdown-codeblock{background:#0c0b20!important;border:1px solid rgba(139,124,246,.14)!important;text-shadow:none}
.dark [data-thread-terminal-drawer]{border-top:1px solid rgba(139,124,246,.16)!important}
.dark [data-thread-details-card]{background:rgba(12,10,30,.85)!important;backdrop-filter:blur(12px);border-color:rgba(139,124,246,.16)!important}
.dark [data-slot="dialog-popup"],.dark [data-slot="popover-popup"],.dark [data-slot="menu-popup"]{border-color:rgba(139,124,246,.18)!important}
.dark ::-webkit-scrollbar{width:10px;height:10px}
.dark ::-webkit-scrollbar-thumb{background:#262048;border-radius:8px;border:2px solid transparent;background-clip:padding-box}
.dark [data-slot="scroll-area-thumb"]{background:#2a2450}
